INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112595, 'spa', 'Porción, parte asignada', 'Una porción o asignación designada, ya sea de alimento, ofrendas del templo o provisiones distribuidas al personal cúltico. En 2 Crónicas 31:3 es la contribución del rey para los holocaustos; en Nehemías 12:44 y 13:10 designa las porciones de los levitas y cantores prescritas por la Torá. Figuradamente, en el Salmo 16:5 Dios mismo es la porción del salmista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112599, 'spa', 'Cuadrillas de trabajo forzado o servidumbre obligatoria impuesta sobre pueblos s', 'Cuadrillas de trabajo forzado o servidumbre obligatoria impuesta sobre pueblos sometidos, como las levas de obreros de Salomón y las poblaciones cananeas sometidas a trabajos forzados (Jos 16:10; 17:13). La expresión מַס עֹבֵד (''corvea laboral'') en Gn 49:15 y Ex 1:11 especifica la forma más severa de este servicio. Casi todas las ocurrencias reflejan la compulsión física del trabajo obligatorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112608, 'spa', 'Tributo monetario o impuesto exigido a un pueblo conquistado o sometido, distint', 'Tributo monetario o impuesto exigido a un pueblo conquistado o sometido, distinto de la conscripción laboral. Atestiguado claramente solo en Est 10:1, donde Asuero impone מַס sobre la tierra y las costas. Este desarrollo semántico tardío, de cuadrilla de trabajo a pago tributario, es paralelo al uso arameo y del hebreo posbíblico, donde el cognado pasó a significar ''impuesto'' en vez de ''trabajo forzado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112612, 'spa', 'Alrededores, entorno', 'Área circundante, alrededores, en derredor. Describe el cercamiento espacial: los lugares en torno a Jerusalén donde sacerdotes paganos quemaban incienso (2 R 23:5), los grabados decorativos ''alrededor'' de los muros del templo (1 R 6:29) y las nubes dirigidas ''por todos lados'' (Job 37:12). El español ''alrededor'' y el francés ''autour'' reflejan consistentemente este sentido espacial de circunvalación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112613, 'spa', 'Calabozo, prisión', 'Un calabozo o prisión, un lugar donde las personas son encerradas, derivado directamente de la raíz סָגַר (cerrar, confinar). El salmista clama «saca mi alma del calabozo» (Sal 142:7), usando el encarcelamiento como metáfora de angustia existencial. Isaías 42:7 lo empareja con la ceguera: el siervo de Dios «sacará a los presos del calabozo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112614, 'spa', 'Herrero, cerrajero', 'Un herrero o cerrajero, artesano metalúrgico especializado en forjar, especialmente cerraduras e implementos de hierro. Usado colectivamente de la clase artesanal exiliada de Jerusalén: «todos los artesanos y los herreros» (2 R 24:14, 16). Jeremías lo reitera en su visión de los higos buenos y malos, enumerando a los deportados incluyendo «los artesanos y los herreros» (Jer 24:1; 29:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112618, 'spa', 'Paneles o marcos decorativos (plural) insertados en los laterales de las bases d', 'Paneles o marcos decorativos (plural) insertados en los laterales de las bases de bronce del templo de Salomón, frecuentemente descritos junto a grabados de leones, bueyes y querubines. Las descripciones arquitectónicas detalladas de 1 Reyes 7:28-36 emplean este término repetidamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112619, 'spa', 'Borde, marco o reborde que rodea un objeto sagrado, especialmente el marco ornam', 'Borde, marco o reborde que rodea un objeto sagrado, especialmente el marco ornamental que circunda la mesa de los panes de la proposición en el tabernáculo. Éxodo 25:25 especifica un marco de un palmo de ancho con una moldura de oro alrededor. La distinción respecto al sentido 1 es la de un borde singular frente a múltiples paneles insertados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112627, 'spa', 'Fortaleza, baluarte o lugar cerrado de refugio, de donde la gente sale temblando', 'Fortaleza, baluarte o lugar cerrado de refugio, de donde la gente sale temblando en reverencia ante Dios. En 2 Samuel 22:46 y Salmo 18:45, las naciones extranjeras salen aterradas de sus fortalezas, y Miqueas 7:17 las compara con reptiles arrastrándose desde sus escondites.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112637, 'spa', 'Derretir o disolver', 'Causar que algo se derrita, disuelva o fluya, ya sea literalmente (hielo que se derrite) o metafóricamente (corazones que desfallecen de temor, llanto que inunda el lecho, el juicio divino que consume posesiones). El hilo común es la transformación de lo sólido y estable a lo líquido e inestable, aplicable tanto a fenómenos naturales como a estados emocionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112640, 'spa', 'Prueba o lugar de prueba', 'Nombre propio de un lugar en el desierto donde Israel probó a Dios, derivado de la raíz que significa «probar» o «tentar». En ciertos contextos funciona como sustantivo común que designa las pruebas o señales que Dios realizó contra Egipto. Esta ambigüedad entre topónimo y nombre común simboliza la perpetua tentación humana de cuestionar la fidelidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112641, 'spa', 'Topónimo del desierto', 'Nombre propio del itinerario en el desierto que designa el sitio donde Israel puso a Dios a prueba dudando de su presencia y provisión. El nombre mismo significa «prueba», constituyendo un memorial permanente de un fracaso de fe. Las referencias posteriores lo emplean como ejemplo admonitorio: «No pongan a prueba al Señor como lo hicieron en Masá».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112642, 'spa', 'Velo facial', 'Las traducciones identifican uniformemente un velo o cobertura facial: en español «velo», en francés «voile». Éxodo 34:33 describe a Moisés colocándose el velo después de que el pueblo viera el resplandor de su rostro. El versículo 34 establece su práctica: lo retiraba ante Dios y lo reponía al enseñar al pueblo. Pablo retoma esta imagen en 2 Corintios 3 para reflexionar sobre la revelación y la transformación espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112646, 'spa', 'Mezclar bebidas', 'Mezclar o combinar una bebida, especialmente vino con especias. En Pr 9:2, 5, la Sabiduría personificada ''ha mezclado su vino'' como parte de su espléndido banquete, e Is 5:22 condena a los expertos ''en mezclar bebida fuerte.'' La mezcla antigua realzaba el sabor con especias, no diluía con agua, distinción que el léxico BDB señala cuidadosamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112648, 'spa', 'Pantalla o cortina que sirve como separación en las entradas del Tabernáculo', 'Pantalla o cortina que sirve como separación en las entradas del Tabernáculo: los colgantes de la puerta del atrio (Ex 27:16; 38:18), la entrada de la tienda de reunión (Ex 26:36–37; 36:37) y los asociados al velo del Lugar Santísimo. Casi las 22 ocurrencias se concentran en Éxodo 25–40 y Números 3–4, vinculando este sentido estrechamente a la legislación del santuario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112653, 'spa', 'Cubierta o pantalla protectora usada para ocultar o resguardar, fuera del contex', 'Cubierta o pantalla protectora usada para ocultar o resguardar, fuera del contexto del Tabernáculo. En 2 Samuel 17:19 una mujer la extiende sobre un pozo para esconder a Jonatán y Ahimaas. El Salmo 105:39 describe a Dios extendiendo una nube ''como cubierta'' sobre Israel. En Isaías 22:8 se retira la ''cubierta de Judá'', dejando expuestas las defensas de la nación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112659, 'spa', 'Ídolo de metal formado vertiendo material fundido en un molde', 'Ídolo de metal formado vertiendo material fundido en un molde. Los episodios del becerro de oro (Ex 32:4, 8; Dt 9:16; Neh 9:18; Sal 106:19) definen el prototipo; el término aparece en prohibiciones (Ex 34:17; Lv 19:4) y en condenas proféticas (Is 42:17; Nah 1:14). Frecuentemente emparejado con פֶּסֶל (imagen tallada), se convirtió en término estándar para denunciar la idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112669, 'spa', 'Libación, cubierta o alianza tejida', 'Libación, cubierta o alianza tejida: algo ''derramado'' en el contexto de hacer un pacto sin Dios. Solo aparece en Isaías 30:1, donde Israel teje una alianza con Egipto que no procede del Espíritu de Dios. BDB lo conecta con la raíz נָסַךְ (derramar) en lugar de vincularlo al sentido de fundición metalúrgica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112677, 'spa', 'Pobre o necesitado', 'Describe a alguien que es pobre o necesitado, usado exclusivamente por Qohélet para explorar la relación entre sabiduría, pobreza y poder social. Aunque las traducciones multilingües lo vierten como simple pobreza económica, su origen como préstamo del acadio podría sugerir categorías sociales específicas. La ironía del Predicador es contundente: la sabiduría del pobre puede salvar una ciudad, pero la sociedad la olvida rápidamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112678, 'spa', 'Almacén, ciudad de aprovisionamiento', 'Un almacén o ciudad de aprovisionamiento, es decir, una instalación fortificada destinada a acumular provisiones, grano y suministros. Las siete apariciones del término designan el mismo referente básico, variando solo en forma gramatical (con artículo, conjunción o estado constructo). En Éxodo 1:11 se refiere a las ciudades de Pitón y Ramsés que Israel construyó bajo trabajo forzado para Faraón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112686, 'spa', 'El sentido principal', 'El sentido principal: una calzada o camino público elevado, construido para el tránsito entre ciudades o regiones. Abarca la gran mayoría de las apariciones — desde la petición de Israel de usar el camino real por Edom (Nm 20:19) hasta las rutas de escape en batalla (Jue 20:31-45; 21:19), el camino donde yacía el cuerpo de Amasa (2 S 20:12-13), y las grandes calzadas proféticas de Isaías (11:16; 19:23; 33:8; 40:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112693, 'spa', 'Una escalera o tramo de peldaños — un medio construido de ascenso dentro de un e', 'Una escalera o tramo de peldaños — un medio construido de ascenso dentro de un edificio. Este sentido especializado aparece únicamente en 2 Crónicas 9:11, donde Salomón usa madera de sándalo para hacer מְסִלּוֹת para la casa del SEÑOR y el palacio real. El contexto arquitectónico lo distingue del significado de camino abierto, aunque la metáfora subyacente de una vía elevada y preparada los conecta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112697, 'spa', 'El curso, órbita o trayectoria fija de los cuerpos celestiales', 'El curso, órbita o trayectoria fija de los cuerpos celestiales. En el Cántico de Débora, ''desde sus órbitas las estrellas pelearon contra Sísara'' (Jue 5:20). La metáfora es vívida: así como una calzada es una ruta predeterminada, las estrellas recorren sus caminos señalados por Dios a través del cielo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112709, 'spa', 'Clavo de sujeción', 'Clavos de metal usados en construcción, fijación de objetos o unión de materiales. Los contextos abarcan desde la edificación del templo (clavos de hierro y oro) hasta la burla profética contra ídolos que necesitan clavos para mantenerse en pie. El uso metafórico en Eclesiastés («dichos como clavos bien clavados») aprovecha la idea de firmeza inherente al clavo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112710, 'spa', 'Sentido intransitivo dominante en Nifal', 'Sentido intransitivo dominante en Nifal: derretirse, disolverse o volverse líquido. Abarca tanto el derretimiento físico — el maná disolviéndose bajo la luz solar (Éx 16:21), la cera ante el fuego (Sal 68:2), las montañas en la teofanía divina (Sal 97:5; Mi 1:4) — como el uso figurado mucho más frecuente donde los corazones ''se derriten'' de terror. Josué 2:11 y 5:1 describen cómo el valor cananeo se derritió ante Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112713, 'spa', 'Sentido especializado del participio Nifal que transmite la idea figurada de alg', 'Sentido especializado del participio Nifal que transmite la idea figurada de algo sin valor o debilitado. En 1 Samuel 15:9, el ganado que Saúl perdonó se describe como ''desvanecido'' o ''sin valor'' — ya disuelto en su estimación. El paso va del derretimiento físico a la degradación cualitativa: lo que se ha ''derretido'' ha perdido toda su sustancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112719, 'spa', 'Sentido raro del infinitivo constructo Qal', 'Sentido raro del infinitivo constructo Qal: consumirse o desgastarse gradualmente. Aparece en Isaías 10:18, donde la gloria de Asiria se consume ''como el consumirse de un enfermo''. A diferencia del dramático derretimiento del Nifal, esta forma implica un deterioro lento y progresivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112720, 'spa', 'Sentido causativo Hifil', 'Sentido causativo Hifil: hacer derretir, provocar que los corazones se disuelvan. En Deuteronomio 1:28 los espías ''hicieron derretir nuestro corazón'' con su informe aterrador. El tronco causativo asigna culpa y agencia donde el Nifal deja el derretimiento como una experiencia que simplemente le sucede al sujeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112725, 'spa', 'Jornada, etapa de marcha', 'Acción de levantar campamento, ponerse en marcha, o una etapa individual en un recorrido más extenso — usado casi exclusivamente para el itinerario de Israel por el desierto. El regreso escalonado de Abram desde Egipto (Gn 13:3), la partida de Israel del Sinaí (Nm 10:12, 28) y el catálogo completo de las cuarenta y dos estaciones en el desierto (Nm 33:1-2) emplean este término. Éxodo 17:1 y 40:36, 38 vinculan las etapas con el movimiento de la nube.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112737, 'spa', 'lamento, lamentación', 'Llanto fuerte y demostrativo, ya sea por los muertos, en respuesta a una calamidad o como acto de contrición penitencial. Duelo fúnebre: la elaborada aflicción por Jacob en Atad (Gn 50:10) y el luto anticipado de Zacarías 12:10-11. Lamentación nacional bajo juicio: Amós 5:16-17 llena ciudad y campo de lamento, y Miqueas 1:8 lo compara al aullido de chacales. Aflicción penitencial: Isaías y Joel lo vinculan con el ayuno y el arrepentimiento comunitario (Jl 2:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112745, 'spa', 'Forraje para ganado', 'Forraje o pienso para el ganado, especialmente asnos y camellos durante los viajes. Siempre aparece como parte de una escena de hospitalidad: el anfitrión provee forraje para los animales de los huéspedes como muestra de bienvenida y cuidado. Dado junto con paja (Gn 24:25), probablemente se refiere a una mezcla de grano como alimento, confirmando un significado único y estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112747, 'spa', 'Costra cutánea ritual', 'Costra o erupción escamosa que requería inspección sacerdotal para determinar la pureza ritual. Las tres apariciones (Lv 13:6-8) describen al sacerdote examinando si la erupción se ha extendido o permanece contenida, lo cual determina el estado ritual de la persona. Su función es diagnóstica dentro del código de pureza levítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112748, 'spa', 'número, cuenta, total', 'Sentido cuantitativo: un número, cuenta o total de personas o cosas (131x), el núcleo masivo del uso de esta palabra. Aparece en constructo («número de»), con sufijos pronominales («su número»), con preposiciones («según el número de») y en el modismo en mispár («sin número, innumerable»). Éxodo 16:16 prescribe recoger el maná «según el número de personas»; Levítico 25:15 calcula el precio de un campo según el número de años.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112764, 'spa', 'pocos, escasez', 'Sentido idiomático que expresa escasez o pequeñez numérica (2x): Nm 9:20 y Dt 4:27, donde mispár aparece en la frase meté mispár («hombres de número»), es decir, «pocos hombres». En Deuteronomio 4:27 el Señor advierte: «quedaréis pocos en número entre las naciones». La paradoja es elegante: la misma palabra que designa «número» pasa a significar «contablemente pequeño», sugiriendo que quienes se pueden contar fácilmente son insignificantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112767, 'spa', 'relato, narración', 'Una sola aparición en Jueces 7:15 donde mispár parece significar «el relato de, la narración de» un sueño: Gedeón oye «el relato del sueño y su interpretación». Aquí el sustantivo conserva el sentido narrativo de la raíz verbal safar («relatar, contar») en lugar de su sentido numérico. El español relato de y el alemán Erzählung seleccionan vocabulario narrativo, confirmando la distinción semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112785, 'spa', 'Escondite, lugar secreto', 'Sustantivo masculino que significa escondite, lugar secreto o escondrijo — un sitio oculto a la vista ordinaria. Se emplea en dos campos semánticos principales: (a) la emboscada o acecho de los malvados, comparado con un león agazapado al acecho (Sal 10:8-9; 17:12; cf. Hab 3:14), o enemigos que disparan desde la ocultación (Sal 64:4); (b) lugares ocultos de refugio o misterio más allá de la percepción humana — Dios desafía ''¿puede alguien esconderse en lugares secretos?'' (Jer 23:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112795, 'spa', 'Vado o paso', 'Punto de cruce o acción de cruzar. En el vado del Jaboc (Gn 32:22), Jacob situó a su familia antes de su lucha. El paso de Micmas (1 S 13:23) era un punto estratégico controlado por los filisteos. Isaías 30:32 lo emplea metafóricamente para cada golpe de la vara disciplinaria de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112796, 'spa', 'Vado, paso, pasaje', 'Punto de cruce en el terreno: vado de río, paso de montaña o pasaje fortificado. El plural מַעְבָּרוֹת designa los vados del Jordán en las narrativas de conquista y jueces (Jos 2:7; Jue 3:28; 12:5-6), mientras que el singular en 1 Samuel 14:4 e Isaías 10:29 señala desfiladeros rocosos. Jeremías 51:32 lo extiende a pasajes defensivos de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112802, 'spa', 'El surco o rodada dejado por ruedas o pies, usado casi exclusivamente en lenguaj', 'El surco o rodada dejado por ruedas o pies, usado casi exclusivamente en lenguaje figurado para el curso moral o espiritual de la vida de una persona. Proverbios y los Salmos lo asocian con ''justicia'' (Sal 23:3), ''rectitud'' (Pr 4:11) y ''bondad'' (Pr 2:9), pero también lo aplican a las sendas tortuosas de los malvados (Pr 2:15; Is 59:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112804, 'spa', 'Campamento defensivo circular formado disponiendo carros en anillo, atestiguado ', 'Campamento defensivo circular formado disponiendo carros en anillo, atestiguado únicamente en las narraciones de David y Saúl (1 S 17:20; 26:5, 7). La terminación direccional hebrea en הַמַּעְגָּלָה (''hacia el campamento'') confirma su significado concreto y espacial, distinguiéndolo claramente del sentido figurado de senda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112814, 'spa', 'Resbalar, deslizar (Qal)', 'La raíz Qal abarca resbalar, deslizarse y vacilar, siempre con los pies o pasos como sujeto. La confianza del salmista en que sus pies «no resbalaron» (2 S 22:37 = Sal 18:36) y que sus pasos «no vacilarán» (Sal 37:31) forman una teología de estabilidad fundada en la fidelidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112818, 'spa', 'Hacer tambalear (Hifil)', 'El Hifil causativo significa hacer tambalear o temblar a alguien, atestiguado solo en Sal 69:23, donde el salmista pide que Dios haga temblar continuamente los lomos de sus enemigos. Este uso causativo se distingue claramente del Qal simple, añadiendo una dimensión de fuerza impuesta sobre otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112821, 'spa', 'Manjar o deleite', 'Comida lujosa o estilo de vida delicado, asociado a la prosperidad y frecuentemente a entornos reales. La evidencia interlingüística muestra cierta divergencia: «manjares/delicias» (alimento) frente a «delicadamente» (modo). La mayoría de los contextos subrayan la comida rica como símbolo de bendición o riqueza, y Lamentaciones ilustra cómo el juicio invierte esa condición social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112825, 'spa', 'Las entranas como sede de emociones profundas', 'Las entranas como sede de emociones profundas: angustia, anhelo, ternura y compasion, donde el vientre mas que el corazon carga con el peso del sentimiento. Con 10 apariciones, este sentido metaforico surge cuando Job declara ''mis entranas se agitan sin descanso'' (Job 30:27), cuando el salmista clama que ''mi corazon es como cera derretida dentro de mis entranas'' (Sal 22:14), y cuando el amado provoca conmocion interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112826, 'spa', 'El vientre, las entranas o los lomos como fuente de descendencia', 'El vientre, las entranas o los lomos como fuente de descendencia: el organo procreador del cual nacen los hijos, frecuentemente en la frase ''de tus entranas'', que significa ''tus propios descendientes biologicos''. Con 10 apariciones, este sentido gobierna la promesa del pacto abrahamico: ''el que saldra de tus entranas sera tu heredero'' (Gn 15:4), el oraculo a Rebeca sobre ''dos naciones en tu vientre'' (Gn 25:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112827, 'spa', 'Las entranas, intestinos u organos internos como partes fisicas del cuerpo, en c', 'Las entranas, intestinos u organos internos como partes fisicas del cuerpo, en contextos de heridas, enfermedad, digestion o descripcion anatomica. Con 12 apariciones, este sentido se manifiesta de forma mas grafica cuando Joab apunala a Amasa y ''derramo sus intestinos por tierra'' (2 Sam 20:10), y en el relato de la fatal enfermedad intestinal del rey Joram: ''se le salieron las entranas a causa de su enfermedad'' (2 Cr 21:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112850, 'spa', 'Una fortaleza fisica, baluarte o lugar fortificado', 'Una fortaleza fisica, baluarte o lugar fortificado: una estructura militar o arquitectonica que brinda defensa. Este sentido principal (25 apariciones) abarca el altar-fortaleza de Gedeon (Jue 6:26), las fortalezas de Tiro y Sidon (Is 23:11, 14), los baluartes militares en las visiones apocalipticas de Daniel (Dn 11:10, 38-39), y la celebracion ''Dios es nuestra fortaleza'' en el Salmo 108:8 donde la metafora arquitectonica aun resuena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112851, 'spa', 'Un lugar de refugio o seguridad, usado metaforicamente de Dios como amparo perso', 'Un lugar de refugio o seguridad, usado metaforicamente de Dios como amparo personal y protector de los justos. Diez apariciones se concentran en los Salmos: ''El SENOR es mi fortaleza'' (Sal 31:2, 4), ''El es refugio para los oprimidos'' (Sal 37:39), ''Tu eres mi Dios de refugio'' (Sal 43:2) y la confesion fundamental de 2 Sam 22:33.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112857, 'spa', 'Fuerza abstracta o poder protector, enfatizando la potencia y la capacidad mas q', 'Fuerza abstracta o poder protector, enfatizando la potencia y la capacidad mas que un lugar fisico o un refugio personal. Solo 2 apariciones portan esta lectura puramente abstracta: la declaracion de Nehemias ''el gozo del SENOR es vuestra fortaleza'' (Neh 8:10) y la afirmacion del Salmo 60:7 donde מָעוֹז designa el poder protector soberano de Dios sobre su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112883, 'spa', 'Morada, habitación, residencia — especialmente de Dios, ya sea en el cielo o en ', 'Morada, habitación, residencia — especialmente de Dios, ya sea en el cielo o en el templo. Deuteronomio 26:15 llama al cielo ''la morada de tu santidad,'' y Jeremías 25:30 describe al SEÑOR rugiendo desde su santa morada en lo alto. 2 Crónicas 30:27 y 36:15 lo usan para el templo como residencia terrenal de Dios, mientras que el Salmo 26:8 expresa el amor del adorador por ''el lugar donde habita tu gloria.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112885, 'spa', 'Guarida, cubil, refugio de animales — especialmente chacales — evocando desolaci', 'Guarida, cubil, refugio de animales — especialmente chacales — evocando desolación y ruina. Jeremías aplica esta palabra repetidamente a ciudades bajo juicio divino: ''Haré de Jerusalén guarida de chacales'' (Jer 9:11; 10:22; 49:33; 51:37). Nahúm 2:12 llama a Nínive ''cubil de leones,'' donde el depredador traía presas para sus cachorros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112889, 'spa', 'Refugio o amparo al que uno huye buscando protección, enfatizando la seguridad m', 'Refugio o amparo al que uno huye buscando protección, enfatizando la seguridad más que la simple residencia. El Salmo 71:3 declara a Dios ''roca de refugio,'' y el Salmo 91:9 se dirige al fiel: ''Has puesto al SEÑOR como tu refugio.'' El cambio de morada a defensa es sutil pero real; aquí מָעוֹן trasciende la habitación para convertirse en la seguridad que Dios mismo proporciona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112897, 'spa', 'Maón (topónimo)', 'Ciudad en la serranía de Judá al sur de Hebrón y su desierto circundante. Josué 15:55 la lista entre las ciudades de Judá; su desierto es escenario de la huida de David ante Saúl (1 S 23:24-25) y la hacienda de Nabal (1 S 25:2). En 1 Crónicas 2:45 figura como nombre de clan en la genealogía calebita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112901, 'spa', 'Guarida de animales', 'Guarida, madriguera o cubil de animales salvajes, particularmente leones y bestias del campo. Evoca el lugar recóndito y protegido donde los depredadores descansan y al que regresan. Amós 3:4 pregunta retóricamente si un león ruge desde su guarida sin presa; Job 37:8 y 38:40 describen bestias agazapadas en sus cubiles; Salmo 104:22 retrata a los animales recogidos en sus guaridas al alba. Nahúm 2:13 también emplea el término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112906, 'spa', 'Morada o refugio', 'Morada, habitación o refugio aplicado a residencias humanas o divinas. Deuteronomio 33:27 emplea esta palabra en una de las declaraciones más memorables de las Escrituras: ''el Dios eterno es tu meʿonah'' — tu refugio y amparo. Salmo 76:2 sitúa la morada de Dios en Sion. El término también aparece en Jeremías 21:13 y Sofonías 3:7 para habitaciones humanas bajo juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112911, 'spa', 'Meunim (grupo étnico)', 'Grupo étnico ubicado en los márgenes meridionales de Canaán. Aparecen como adversarios derrotados por colonos simeonitas (1 Cr 4:41) y por el rey Uzías (2 Cr 26:7), y como netineos que retornaron de Babilonia (Esd 2:50). La variación Ketiv/Qere y la forma Minaioi de la Septuaginta reflejan incertidumbre sobre su identidad precisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112921, 'spa', 'Hifil causativo', 'Hifil causativo: hacer pocos, reducir en número o cantidad, dar o recoger menos. Es el sentido más frecuente con trece apariciones. Los que recogieron poco maná no tuvieron escasez (Éx 16:17-18); el que dé menos no reducirá el medio siclo (Éx 30:15); Dios ''disminuirá'' las bestias de la tierra (Lv 26:22). El español ''disminuir'' refleja consistentemente este significado causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112923, 'spa', 'Qal intransitivo', 'Qal intransitivo: ser o hacerse pocos en número, disminuir o menguar. Un pueblo que no se multiplica ''se hace poco'' (Jer 29:6; 30:19); el resto de los guerreros de Cedar ''será escaso'' (Is 21:17); el salmista observa cómo los afligidos ''fueron disminuidos'' (Sal 107:39). Proverbios 13:11 lo aplica a la riqueza: ''la riqueza adquirida de prisa se disminuye.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112926, 'spa', 'Qal intransitivo', 'Qal intransitivo: ser demasiado pequeño, insuficiente o inadecuado para un propósito determinado. En Éxodo 12:4, si una familia ''es demasiado pequeña'' para un cordero pascual entero, debe compartir con un vecino — una regla práctica con profundas implicaciones comunitarias. Nehemías 9:32 ruega que la adversidad no ''parezca poca'' delante de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112936, 'spa', 'Piel factitivo', 'Piel factitivo: hacerse pocos o disminuidos, con énfasis en el estado resultante de reducción. Esta rara forma intensiva aparece en Eclesiastés 12:3, describiendo a las moledoras que ''se han hecho pocas'' — parte del retrato alegórico del envejecimiento de Qohélet, donde ''las que muelen cesan porque son pocas.'' El Piel intensifica lo que el Qal expresa simplemente, subrayando la completitud de la disminución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112939, 'spa', 'un poco, cantidad pequeña', 'Sentido cuantitativo básico: «un poco» de algo, una cantidad pequeña. Gn 18:4 («sea traída un poco de agua») y Gn 24:17 («dame de beber un poco de agua») son paradigmáticos. Español poco, francés peu y alemán wenig convergen en este significado central. La palabra funciona como sustantivo que rige una construcción partitiva, indicando una porción pequeña de un todo mayor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112940, 'spa', 'pocos en número', 'Aplicado a personas o elementos contables: «pocos en número». Dt 7:7 declara que Israel era «el más pequeño de todos los pueblos»; Gn 47:9 lo usa de los años «pocos y malos» de Jacob. Lv 25:52 y Nm 26:54 lo emplean en fórmulas legales que distribuyen la herencia según si una tribu tiene muchos o pocos miembros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112943, 'spa', 'casi, por poco', 'Compuesto preposicional ki-me''at (כִּמְעַט): «casi, por poco, apenas». Sal 73:2 («por poco resbalaron mis pies»), Sal 94:17 («casi habitó mi alma en el silencio»), Gn 26:10 («por poco se habría acostado alguno del pueblo con tu mujer»). Español casi/apenas, francés presque/à peine y alemán beinahe confirman la función adverbial aproximativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112947, 'spa', '¿es poca cosa? (retórico)', 'Construcción interrogativa retórica ha-me''at (הַמְעַט): «¿es poca cosa?» o «¿acaso es poco?». Usada en desafíos y reproches proféticos: Nm 16:9 («¿es poco para vosotros que Dios os haya separado?»), Gn 30:15, Jos 22:17. La construcción presupone que el destinatario debería sentirse satisfecho con lo que ya ha recibido, y su respuesta implícita es siempre «no, no es poco».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112950, 'spa', 'pequeño, de poco valor', 'Sentido evaluativo que indica pequeñez en valor, estatus o importancia. Pr 10:20 («el corazón de los impíos es de poco valor») y Ez 11:16 («he sido para ellos un pequeño santuario») usan la palabra para evaluar calidad o rango. Dn 11:34 habla de una ayuda que es «pequeña», insuficiente o insignificante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112968, 'spa', 'pronto, en un instante', 'Sentido temporal: «pronto, en un momento, dentro de poco». Sal 81:14 («pronto sometería yo a sus enemigos») y Sal 2:12 («pues se enciende de pronto su ira») muestran el desplazamiento de la pequeñez espacial a la brevedad temporal. Esd 9:8 lo usa del «breve momento» de la gracia de Dios, y Job 32:22 advierte que el Hacedor de Elihú pronto lo eliminaría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112969, 'spa', 'poco a poco, gradualmente', 'Modismo distributivo me''at me''at (מְעַט מְעַט): «poco a poco, gradualmente». Éx 23:30 («poco a poco los echaré de delante de ti») y Dt 28:38 («recogerás poco») demuestran el sentido iterativo e incremental. Español poco a poco y francés petit à petit son paralelos estructurales exactos. Este patrón reduplicativo, común en las lenguas semíticas, convierte el cuantificador simple en marcador de progresión gradual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112985, 'spa', 'Un manto exterior o capa sin mangas que se vestía sobre la כְּתֹנֶת (túnica), as', 'Un manto exterior o capa sin mangas que se vestía sobre la כְּתֹנֶת (túnica), asociado a personas de rango, profetas y sacerdotes. En el ámbito sacerdotal, el manto del efod se teñía completamente de azul con campanillas y granadas en su orla (Éx 28:31-34). En los relatos narrativos, el manto desgarrado de Samuel simboliza el reino arrancado de Saúl (1 S 15:27-28), y Job rasga su manto en señal de duelo (Job 1:20). Rasgar el מְעִיל se convirtió en un gesto clásico de dolor y horror.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112998, 'spa', 'Una fuente natural de agua donde el agua brota de la tierra, usada para manantia', 'Una fuente natural de agua donde el agua brota de la tierra, usada para manantiales geográficos, fuentes y aguas subterráneas. Pasajes clave incluyen los cosmológicos ''manantiales del abismo'' (Gn 7:11; 8:2), los manantiales cegados por Ezequías (2 Cr 32:4), y la fuente escatológica que brota del templo (Jl 3:18). El español ''manantial'' y el alemán Quelle captan directamente el sentido literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113003, 'spa', 'Un manantial o fuente usados metafóricamente para designar el origen, la vitalid', 'Un manantial o fuente usados metafóricamente para designar el origen, la vitalidad o la fuente interior de vida y bendición de una persona. En Cantares 4:12, 15 la amada es una fuente sellada de jardín; Proverbios 5:16 pregunta si las fuentes de uno deben derramarse por las calles; y el Salmo 87:7 celebra a Sion como la fuente de todos los manantiales propios. Oseas 13:15 invierte la imagen, advirtiendo que la fuente de Efraín se secará.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113013, 'spa', 'Apretar o clavar', 'Presionar, estrujar o clavar con fuerza. Levítico 22:24 prohíbe ofrecer animales cuyos testículos estén magullados o aplastados. En 1 Samuel 26:7, la lanza de Saúl aparece clavada en tierra junto a su cabecera. Ezequiel 23:3 emplea el término para la violencia sexual: pechos estrujados en el abrazo idolátrico de Egipto. El hilo común es la presión o penetración contundente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113014, 'spa', 'Nombre propio para múltiples personas y un territorio', 'Nombre propio para múltiples personas y un territorio: hijo de Nacor por medio de Reúma (Gn 22:24), esposa gesurita de David y madre de Absalón (2 S 3:3), y la reina madre depuesta por Asá (1 R 15:13). Geográficamente, el pequeño principado arameo al sur del monte Hermón (Jos 13:13; 2 S 10:6). La Septuaginta lo transcribe como Μααχα.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113020, 'spa', 'Maacateo (gentilicio)', 'Adjetivo gentilicio derivado de Maacá (מַעֲכָה), región aramea al pie del monte Hermón. Se usa colectivamente con הַמַּעֲכָתִי para designar a la población maacatea que Israel no despojó (Dt 3:14; Jos 12:5; 13:11, 13), e individualmente para identificar a personas como uno de los guerreros de David (2 S 23:34) y Jaazanías (2 R 25:23; Jer 40:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113023, 'spa', 'Actuar infielmente o cometer sacrilegio contra Dios', 'Actuar infielmente o cometer sacrilegio contra Dios: el sentido verbal que describe el acto de quebrantar el pacto, aplicado a individuos (Acan en Jerico, Jos 7:1; Uzias en el templo, 2 Cr 26:16) y colectivamente a Israel (Lv 26:40; Esd 10:2). La construccion caracteristica מָעַל מַעַל (''cometio infidelidad'') intensifica la gravedad de la ofensa. A diferencia de terminos generales para pecado, este verbo denota especificamente la violacion de lo sagrado o pactado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113032, 'spa', 'Infidelidad o traicion como sustantivo o infinitivo absoluto', 'Infidelidad o traicion como sustantivo o infinitivo absoluto: el estado abstracto de quebrantamiento del pacto, mas que el acto en si (2 Cr 28:19, donde Acaz ''hizo que Juda actuara desenfrenadamente y fue sumamente infiel''; 2 Cr 36:14, donde sacerdotes y pueblo ''multiplicaron la infidelidad''). Aqui el enfasis recae sobre la condicion acumulada e intensificada de deslealtad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113052, 'spa', 'Un acto de infidelidad o violación sacrílega contra Dios o el pacto, que conllev', 'Un acto de infidelidad o violación sacrílega contra Dios o el pacto, que conlleva una carga religiosa más fuerte que el vocabulario general del pecado. En Levítico, describe el uso indebido de bienes consagrados o juramentos falsos respecto a los bienes del prójimo (Lv 5:15; 6:2; Nm 5:6, 12). El Cronista lo emplea para explicar el exilio como consecuencia de la infidelidad corporativa (1 Cr 9:1; 2 Cr 29:19; Esd 9:2). Aparece con frecuencia en la expresión fija מָעַל מַעַל (''cometer infidelidad''), subrayando la gravedad de la ofensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113068, 'spa', 'y arriba (extensión aditiva)', 'Extensión aditiva «y arriba, y en adelante» (~57x): la fórmula característica X wa-ma''lá que marca un límite inferior abierto. «De veinte años y arriba» (Nm 1:3), «de un mes y arriba» (Nm 3:15). Aparece predominantemente en listas censales, requisitos de edad levíticos y especificaciones de medidas. El alemán und-aufwärts y el español y arriba traducen con fidelidad este sentido de umbral cuantitativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113069, 'spa', 'desde arriba (origen)', 'Procedencia u origen desde lo alto (~43x): la preposición compuesta mim-ma''al (con min) indicando que algo proviene de, se extiende desde o se contempla desde una posición superior. Gn 7:20 describe las aguas del diluvio que subieron quince codos «por encima» de las montañas; Éx 25:21 ordena colocar el propiciatorio «encima» del arca. El francés de-au-dessus y el alemán von-oben capturan este matiz ablativo-espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113070, 'spa', 'hacia arriba (direccional)', 'Dirección «hacia arriba, más alto» (~27x): uso adverbial con le- indicando movimiento u orientación hacia una posición más elevada. Éx 25:20 describe las alas de los querubines extendiéndose «hacia arriba»; Dt 28:43 advierte que el extranjero subirá «más y más alto». En 1 Cr 14:2, David percibe que el Señor ha exaltado su reino le-ma''lá, hacia una posición cada vez más alta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113073, 'spa', 'encima, sobre (locativo)', 'Posición locativa «encima de, sobre» (~13x): ubicación estática arriba o sobre algo, típicamente en el compuesto mim-ma''al le-. Gn 22:9 describe a Isaac colocado sobre el altar «encima» de la leña; Éx 20:4 y Dt 5:8 prohíben imágenes de lo que está en los cielos «arriba». La fórmula teológica «los cielos de arriba» (Dt 4:39) sitúa el dominio de Dios en el espacio superior trascendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113089, 'spa', 'Escaleras o peldaños de una estructura — escaleras, gradas o una plataforma elev', 'Escaleras o peldaños de una estructura — escaleras, gradas o una plataforma elevada perteneciente a una edificación. La visión del templo de Ezequiel emplea el término repetidamente para las escaleras de las estructuras de las puertas (Ez 40:31, 34, 37), y Nehemías 9:4 y 12:37 mencionan escaleras o plataformas elevadas en el contexto de asambleas públicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113091, 'spa', 'Subida o paso geográfico — una pendiente, cuesta o paso de montaña ascendente, t', 'Subida o paso geográfico — una pendiente, cuesta o paso de montaña ascendente, típicamente un accidente topográfico con nombre propio que sirve como punto de referencia o frontera. La Subida de Akrabim marca la frontera sur de Judá (Nm 34:4; Jos 15:3; Jue 1:36), la Subida de Adumim se sitúa entre Jerusalén y Jericó (Jos 15:7; 18:17), y la retirada de David por el Monte de los Olivos se narra a lo largo de su ''subida'' (2 S 15:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113102, 'spa', 'Encabezamiento litúrgico fijo, shir hamma''alot, que introduce cada uno de los Sa', 'Encabezamiento litúrgico fijo, shir hamma''alot, que introduce cada uno de los Salmos 120-134. Los ''ascensos'' probablemente se refieren a la procesión de peregrinación que subía al monte del templo de Jerusalén para las tres fiestas anuales. La tradición sugiere que los cantores levíticos se situaban en los quince escalones del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113103, 'spa', 'Escalones o gradas físicas pertenecientes a una estructura, como las puertas del', 'Escalones o gradas físicas pertenecientes a una estructura, como las puertas del templo (Ez 40:6, 22, 26), el altar (Ex 20:26; Ez 43:17), el trono de Salomón (1 R 10:19-20), una casa real (2 R 9:13) o la ciudad de David (Neh 3:15; 12:37). También las gradas graduadas del reloj de sol de Acaz (2 R 20:9-11 = Is 38:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113112, 'spa', 'El acto o ruta abstracta de subir, como el ascenso de Babilonia a Jerusalén (Esd', 'El acto o ruta abstracta de subir, como el ascenso de Babilonia a Jerusalén (Esd 7:9) o la subida de Bet-horón (Jos 10:10). Capta el sentido de un viaje o camino geográfico ascendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113116, 'spa', 'Lugar elevado o piso superior, usado de manera singular en 1 Crónicas 17', 'Lugar elevado o piso superior, usado de manera singular en 1 Crónicas 17:17 donde David habla de que Dios le muestra cosas ''en lo alto'', y en Amós 9:6 que describe los pisos superiores de Dios en el cielo. El sentido pasa de escalones físicos a altura metafórica y exaltación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113121, 'spa', 'Acrabim (topónimo)', 'El topónimo «Acrabim» (Paso de los Escorpiones) aparece en descripciones de los límites del sur de Canaán (Nm 34:4; Jos 15:3; Jue 1:36). Las tradiciones principales lo transliteran — español «Acrabim», inglés «Akrabbim» — tratándolo como topónimo fijo, lo que muestra que el nombre ya se había lexicalizado como referencia geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113122, 'spa', 'Subida, cuesta (geográfico)', 'El sentido de sustantivo común designa una subida física, cuesta o camino ascendente como rasgo geográfico. Usado con preposiciones direccionales («a la subida de», «desde la subida de»), describe un terreno que hay que escalar. El español «subida» capta bien el sentido activo de ascender, distinguiéndolo de una designación estática de cerro o montaña.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113125, 'spa', 'Conducta habitual u obras caracteristicas de personas o comunidades, evaluadas p', 'Conducta habitual u obras caracteristicas de personas o comunidades, evaluadas predominantemente en terminos morales. La frase de Jeremias רֹעַ מַעַלְלֵיכֶם (''la maldad de vuestras obras'', Jer 4:4; 21:12) convoca al arrepentimiento. Oseas 5:4 y 7:2 la aplican a la perversidad arraigada. El uso positivo referido a las obras de Dios en la adoracion (Sal 77:12; 78:7) muestra que el termino es neutro en principio, aunque abrumadoramente negativo en la practica profetica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113145, 'spa', 'Puesto de servicio', 'Puesto o estación: la posición física donde uno permanece de pie para cumplir funciones. Los cantores levíticos permanecieron ''en sus puestos'' durante la Pascua de Josías (2 Cr 35:15), y en 1 Cr 23:28 el puesto levítico definía su función litúrgica. El español ''su puesto'' destaca la naturaleza fija y asignada de esta posición en el culto del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113148, 'spa', 'Profundidades marinas', 'Las honduras literales del oceano o del mar. Dios convirtio ''las profundidades del mar en camino'' para que los redimidos cruzaran (Is 51:10), y Tiro fue quebrantada ''en las profundidades de las aguas'' (Ez 27:34). Este sentido enfatiza tanto el dominio divino sobre las aguas del caos como la inmensidad fisica aterradora del abismo marino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113149, 'spa', 'para que, a fin de que', 'Propósito o resultado: «para que, a fin de que» (196x). Introduce una cláusula que expresa la meta pretendida o el resultado esperado de la acción principal. Gn 12:13: «Di que eres mi hermana, para que (lema''an) me vaya bien». Gn 18:19: Dios escogió a Abraham «a fin de que (lema''an) mande a sus hijos». Español para que, francés afin que y alemán damit marcan este sentido final de modo coherente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113150, 'spa', 'por causa de, en favor de', 'Causa o beneficiario: «por causa de, en consideración a, en favor de» (65x). Uso preposicional con sufijos pronominales o sintagmas nominales que especifican la persona o causa que motiva una acción. Gn 18:24: «¿destruirás el lugar y no lo perdonarás por causa de (lema''an) los cincuenta justos?». 1 Re 11:12-13: «por causa de David tu padre... por causa de Jerusalén». El español por causa de y el francés à cause de capturan con precisión este matiz causal-benefactivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113152, 'spa', 'propósito/causa (ambiguo)', 'Superposición ambigua de propósito y causa (11x), donde ambas lecturas —final y causal— son simultáneamente válidas y el traductor debe elegir. Ezequiel 21:10-15 concentra los casos clave: la espada se afila «lema''an degüelle»: ¿es «para que» (propósito) o «a causa de» (la matanza que motivó el afilado)? La retórica profética explota deliberadamente esta ambigüedad, fusionando intención divina y causalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113166, 'spa', 'Respuesta, réplica', 'Respuesta o réplica verbal en el diálogo. En Proverbios 15:1 la ''blanda respuesta'' (מַעֲנֶה־רַךְ) quita la ira, uno de los proverbios más célebres sobre el poder de las palabras. Proverbios 15:23 celebra la réplica oportuna y 16:1 observa que ''la respuesta de la lengua es de Jehová''. En Job 32:3, 5 Elihú se frustra ante el silencio de los amigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113168, 'spa', 'Propósito, intención', 'Sentido extendido que significa ''propósito'', ''intención'' o ''correspondencia adecuada'': el diseño inherente o fin asignado de algo. Atestiguado únicamente en Proverbios 16:4: ''Todo lo hizo Jehová לְמַעֲנֵהוּ'' — ''para su propósito'' o, más literalmente, ''para su respuesta'', como si cada cosa creada llevara en sí una respuesta al designio del Creador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113170, 'spa', 'Surco de arado', 'Surco o caballón trazado en la tierra. En 1 Samuel 14:14, Jonatán y su escudero abaten filisteos «en el espacio de medio surco de una yugada de tierra», empleando el surco como unidad de medida. El Salmo 129:3 utiliza la imagen dos veces: «Sobre mis espaldas araron los aradores; alargaron sus surcos», representando el sufrimiento de Israel bajo la opresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113179, 'spa', 'Mercancía, bienes comerciales', 'Mercancía, bienes comerciales o géneros: los artículos intercambiados en transacciones comerciales, siempre con sufijo femenino de segunda persona referido a la ciudad de Tiro. Las nueve apariciones se encuentran en Ezequiel 27, el oráculo profético que cataloga el vasto imperio mercantil de Tiro, desde la plata de Tarsis hasta los corderos de Arabia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113182, 'spa', 'oeste', 'El punto cardinal oeste, concebido como el lugar donde se pone el sol. Aparece en descripciones de límites geográficos y orientación direccional, especialmente en Crónicas para asignaciones del templo y divisiones territoriales (1 Cr 7:28; 12:16; 26:16, 18, 30). Emparejado con מִזְרָח (''este'') en declaraciones cósmicas y teológicas sobre la soberanía universal de Dios (Is 43:5; 45:6; 59:19) y la totalidad de su perdón (Sal 103:12). El cognado árabe maghrib, usado hoy para Marruecos y la oración vespertina, conserva la misma etimología solar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113190, 'spa', 'Una camara natural excavada en la roca o subterranea, empleada a lo largo de las', 'Una camara natural excavada en la roca o subterranea, empleada a lo largo de las Escrituras para sepultura (la cueva de Macpela, Gn 23:9-19), ocultamiento y refugio ante enemigos (Jos 10:16-27; Jue 6:2; 1 Sam 13:6; 22:1; 24:3), encuentro divino (Elias en el Horeb, 1 R 19:9-13) y como guarida de fieras (Is 32:14). La expresion de Jeremias מְעָרַת פָּרִצִים (''cueva de ladrones'', Jer 7:11) tiende un puente entre el uso literal y el metaforico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113207, 'spa', 'Línea de batalla, formación militar — la fila organizada de soldados dispuestos ', 'Línea de batalla, formación militar — la fila organizada de soldados dispuestos para el combate. Este es el sentido dominante, abarcando todas las apariciones en 1 Samuel. En 1 Samuel 17:21, Israel y los filisteos disponen ''formación contra formación'' (מַעֲרָכָה לִקְרַאת מַעֲרָכָה). El constructo plural ''filas de Israel'' (1 S 17:10, 45) y ''filas del Dios viviente'' (17:26, 36) subrayan el carácter sagrado de la confrontación bélica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113212, 'spa', 'Hilera, disposición ordenada — una fila o arreglo ordenado de objetos, extendien', 'Hilera, disposición ordenada — una fila o arreglo ordenado de objetos, extendiendo el significado raíz de עָרַךְ más allá del contexto militar. En Éxodo 39:37, las ''lámparas de la hilera'' (נֵרוֹת הַמַּעֲרָכָה) describen las luces del candelabro dispuestas sistemáticamente. Jueces 6:26 usa la palabra para la leña dispuesta sobre un altar en el orden apropiado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113219, 'spa', 'Disposición ritual ordenada', 'La disposición cúltica sistemática o exhibición ordenada de los panes de la proposición en el tabernáculo y el templo. Este sentido enfatiza la institución ritual misma: la práctica continua de colocar pan consagrado ante el SEÑOR. En 1 Crónicas 9:32 los coatitas están a cargo del ''pan de la disposición'', y 2 Crónicas 13:11 lo invoca como prueba de la adoración fiel de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113221, 'spa', 'Hilera, fila, línea', 'Una hilera o línea individual de objetos dispuestos en orden físico, enfocándose en la configuración espacial más que en el sistema ritual amplio. Levítico 24:6-7 especifica ''dos hileras, seis por hilera'' y se refiere al incienso puesto ''sobre la hilera'' como porción memorial. El término destaca la disposición lineal concreta de los panes individuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113225, 'spa', 'hechura, manufactura', 'Artesanía o hechura: la técnica, destreza o producto manufacturado del trabajo artesanal. Predomina en las instrucciones del tabernáculo del Éxodo (93 apariciones): las cortinas son ''obra de artífice'' (Éx 26:1, 31), la rejilla del altar es ''obra de red de bronce'' (Éx 27:4) y las vestiduras sacerdotales requieren ''obra de bordador'' (Éx 28:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113226, 'spa', 'obras de Dios', 'Las obras o actos poderosos de Dios: la actividad divina en la creación, la providencia y la historia de la salvación. La doxología sálmica celebra: ''¡Cuán grandes son tus obras!'' (Sal 92:5; 104:24). Moisés declara que ningún dios puede igualar los מַעֲשִׂים de Dios (Dt 3:24). La expresión מַעֲשֵׂה יהוה designa la intervención soberana del Señor (Is 5:12; 28:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113227, 'spa', 'trabajo, labor, tarea', 'Trabajo, labor o tarea como actividad productiva: el esfuerzo u ocupación en sí, no su producto. Articula el marco sabático — ''seis días harás tu trabajo'' (Éx 23:12) — y abarca la labor de cosecha, las bendiciones deuteronómicas sobre la empresa humana (Dt 14:29; 16:15) y los esfuerzos de reconstrucción posexílica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113232, 'spa', 'hecho, acto, conducta', 'Hecho, acto o conducta sujeta a evaluación moral: el comportamiento humano juzgado como justo o perverso. José acusa a sus hermanos: ''¿Qué acción es esta que habéis hecho?'' (Gn 44:15). La alianza del Éxodo exige ''no harás conforme a sus obras'' (Éx 23:24). Miqueas condena los מַעֲשִׂים de Omrí como gobierno corrupto (Mi 6:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113250, 'spa', 'producto, fruto, rendimiento', 'Producto, fruto o rendimiento: el resultado concreto del trabajo, enfatizando lo que se produce. Ezequiel enumera Damasco comerciando con ''el producto de tus manos'' (Ez 27:16, 18). Habacuc lamenta que el מַעֲשֶׂה del olivo falle (Hab 3:17). Isaías pregunta si la vasija puede decir a su alfarero ''no me hizo'' (Is 29:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113305, 'spa', 'asunto, incidente', 'Uso contextual oscuro o ambiguo, como en 1 Samuel 20:19, donde Jonatán dice a David que vaya al lugar donde se ocultó ''el día del מַעֲשֶׂה'': probablemente ''el asunto'' o ''el incidente'', refiriéndose a un suceso concreto anterior. Es una acepción rara que trata el término como referencia a un evento particular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113319, 'spa', 'Nombre teofórico derivado de מַעֲשֵׂה (''obra'') más Yah', 'Nombre teofórico derivado de מַעֲשֵׂה (''obra'') más Yah. Llevado por músicos levitas (1 Cr 15:18, 20), un capitán bajo Joás (2 Cr 23:1), el padre de un príncipe muerto por Zicrí (2 Cr 28:7), sacerdotes en tiempos de Jeremías (Jer 21:1; 37:3), y varios hombres postexílicos en la comunidad de Esdras-Nehemías. El español ''Maaseías'' y el francés ''Maaséja'' conservan la forma teofórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113323, 'spa', 'Una decima parte del producto, ganado o ingreso consagrada como ofrenda religios', 'Una decima parte del producto, ganado o ingreso consagrada como ofrenda religiosa a Dios o destinada a los levitas, cubriendo 30 de las 32 apariciones. Desde la ofrenda voluntaria de Abraham a Melquisedec (Gn 14:20), pasando por las regulaciones leviticas (Lv 27:30-32; Nm 18:21-26), hasta el llamado de Malaquias a la fidelidad (3:8-10), este sentido abarca toda la legislacion cultual del diezmo en Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113326, 'spa', 'Una fraccion puramente cuantitativa que significa una decima parte, usada en las', 'Una fraccion puramente cuantitativa que significa una decima parte, usada en las medidas de la vision del templo de Ezequiel, donde el homer y el bato se subdividen (Ez 45:11, 14). Este sentido aritmetico, no cultual, se distingue del diezmo religioso por su contexto exclusivamente metrologico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113339, 'spa', 'Mefiboset', 'El nombre propio Mefiboset (מְפִיבֹשֶׁת), también llamado Merib-baal (מְרִיב בַּעַל) en 1 Crónicas 8:34 y 9:40, que identifica al hijo de Jonatán y nieto del rey Saúl. El cambio de Merib-baal a Mefiboset refleja una sustitución escribal deliberada de בֹּשֶׁת (''vergüenza'') por el nombre divino cananeo בַּעַל. Quedó lisiado de ambos pies tras una caída infantil (2 S 4:4) y fue objeto de la lealtad pactual de David hacia Jonatán: restaurado a la heredad de Saúl y sentado a la mesa real (2 S 9), aunque después quedó enredado en la crisis de Absalón por la traición de su siervo Siba (2 S 16; 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113354, 'spa', 'Ídolo abominable', 'Objeto horrendo o abominable, específicamente una imagen idolátrica tan ofensiva que provoca estremecimiento. El término aparece únicamente en el relato de las reformas de Asá, describiendo el ídolo que su abuela/madre hizo para Asera. Las glosas multilingües («horror», «imagen abominable», «ídolo horrible») captan tanto la ofensa religiosa como la repulsión emocional que el vocablo conlleva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113356, 'spa', 'Caída, ruina', 'El sentido dominante de caída, ruina o derrocamiento, que describe el colapso catastrófico de una nación, un rey o una persona impía. Las siete apariciones se sitúan en contextos proféticos o sapienciales: los oráculos de Ezequiel contra Tiro (26:15, 18; 27:27) y Egipto (31:13, 16; 32:10), y el proverbio que afirma que los impíos presencian su propia ruina (Pr 29:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113358, 'spa', 'Cadáver, cuerpo caído', 'Un sentido concreto y físico: cadáver o cuerpo abatido, atestiguado únicamente en Jue 14:8, donde Sansón regresa y encuentra abejas y miel en la מַפֶּלֶת del león que había despedazado. La evidencia multilingüe diverge marcadamente del sentido 1: en español ''el cadáver de'', en inglés ''carcass of'', señalando un cuerpo animal muerto y no una ruina nacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113364, 'spa', 'Censo o designación', 'Revista o censo de personas, nombramiento administrativo o lugar designado, según el contexto. Las glosas interlingüísticas reflejan el rango semántico: «empadronamiento/censo» (recuento de personas), «nombramiento» (designación administrativa) y «lugar señalado» (asignación espacial). El concepto unificador es la designación formal, ya sea contar hombres en edad militar, asignar funcionarios a sus deberes o demarcar un lugar específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113372, 'spa', 'Umbral, dintel inferior', 'El umbral de un edificio, particularmente de un templo o estructura sagrada. La palabra lleva una fuerte asociación con el espacio sacro a lo largo de sus ocho apariciones. En 1 Samuel 5:4-5, el umbral del templo de Dagón adquiere carácter ritual tras la caída del ídolo. Ezequiel sitúa repetidamente la gloria de YHWH en el umbral del templo visionario (Ez 9:3; 10:4, 18; 46:2; 47:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113375, 'spa', 'Como tamo', 'El tamo, residuo ligero de la trilla, utilizado invariablemente en símiles (siempre con כְּ, ''como'') para representar lo insustancial y fácilmente arrastrado por el viento. Se aplica a los impíos (Sal 1:4; 35:5; Job 21:18), a las naciones hostiles dispersadas ante Dios (Is 17:13; 29:5), al poder aplastante de Judá sobre sus enemigos (Is 41:15) y al paso fugaz del tiempo (Os 13:3; Sof 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113378, 'spa', 'Qal: hallar, descubrir', 'Sentido activo primario: hallar, descubrir o localizar algo buscado, perdido o deseado. Cubre la búsqueda intencional (Gn 2:20, donde no se ''halló'' ayuda idónea para Adán), el hallazgo accidental y la expresión idiomática מָצָא חֵן בְּעֵינֵי (''hallar gracia ante los ojos de''), que aparece en Gn 6:8 acerca de Noé.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113382, 'spa', 'Nifal participio: los presentes', 'El participio Nifal usado sustantivamente, especialmente con artículo (הַנִּמְצְאִים), para significar ''los que se hallaban presentes''. Este uso formulaico domina en Crónicas (p. ej., 2 Cr 34:32) para designar a personas reunidas, funcionando casi como término censal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113388, 'spa', 'Nifal: ser hallado', 'El Nifal pasivo: ser hallado, ser descubierto, estar presente o existir. No es simplemente el pasivo del sentido 1, sino que a menudo porta un matiz existencial — ''ninguna levadura será hallada en vuestras casas'' (Éx 12:19). Esta polisemia entre ''ser encontrado'' y ''existir'' es tipológicamente natural en las lenguas semíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113441, 'spa', 'Hifil: entregar, presentar', 'El Hifil causativo: hacer hallar, entregar, presentar. Raro (7 apariciones), concentrado en pasajes rituales levíticos (Lv 9:12-18), donde los hijos de Aarón ''presentaron'' la sangre, y en 2 S 3:8 con el sentido de ''entregar''. La lógica causativa es clara: hacer que algo llegue a su destinatario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113453, 'spa', 'Qal: bastar, ser suficiente', 'Acepción rara que significa ''bastar, ser suficiente'', atestiguada principalmente en Nm 11:22, donde Moisés pregunta si alcanzarán los rebaños y manadas para el pueblo. El camino semántico de ''hallar'' a ''bastar'' pasa por la disponibilidad: lo que se puede hallar es lo que está a mano y, por tanto, lo que alcanza. Solo 3 apariciones claras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113553, 'spa', 'Qal: alcanzar, sobrevenir', 'Alcanzar, sobrevenir o caer sobre: cuando la calamidad, la desgracia o los acontecimientos ''hallan'' a una persona sin búsqueda activa (Dt 4:30; Nm 32:23, ''vuestro pecado os alcanzará''). Este sentido revela a מָצָא como verbo de encuentro desde la perspectiva del objeto, donde el sujeto — a menudo abstracto: mal, angustia — es quien actúa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113602, 'spa', 'Guarnición militar', 'Guarnición, puesto avanzado o posición de soldados estacionados en territorio estratégico. Usado predominantemente para las guarniciones filisteas que amenazaban a Israel durante el reinado de Saúl. Jonatán y su escudero se aproximaron célebremente al matstsav filisteo en Micmas (1 S 14:1, 4, 6), y 2 Samuel 23:14 hace referencia a una guarnición filistea en Belén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113604, 'spa', 'Lugar de estacionamiento', 'Lugar de permanencia o posición fija asignada, ya sea en sentido físico literal o como estación figurada de autoridad. En Josué 4:3 y 4:9, la palabra señala el punto preciso donde los pies de los sacerdotes se mantuvieron firmes en el Jordán — un lugar memorial de significado teofánico. En Isaías 22:19 designa el cargo o posición del cual el mayordomo Sebna será depuesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113610, 'spa', 'Una piedra erguida como memorial, testimonio o marca de limite, asociada a propo', 'Una piedra erguida como memorial, testimonio o marca de limite, asociada a propositos conmemorativos positivos o neutros. Jacob unge su pilar en Betel (Gn 28:18, 22; 31:13), coloca uno en la tumba de Raquel (Gn 35:20) y las piedras de pacto sirven como testigos de acuerdos (Gn 31:45, 51). Absalon erige una como monumento personal (2 Sam 18:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113611, 'spa', 'Una piedra sagrada erguida asociada al culto pagano cananeo, sistematicamente co', 'Una piedra sagrada erguida asociada al culto pagano cananeo, sistematicamente condenada y ordenada a ser destrozada, quebrada o derribada. Los textos legales y profeticos ordenan su destruccion junto con los altares y las aseras (Ex 23:24; 34:13; Dt 7:5; 12:3). Las formas plurales predominan aqui, y Oseas 3:4 incluye la מַצֵּבָה entre los objetos culticos de los que Israel carecera en el exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113627, 'spa', 'Pilar, piedra erguida', 'Pilar o piedra erguida colocada como memorial, marcador sagrado o monumento. Jacob erige y unge una en Betel (Gen 35:14), pone otra sobre la tumba de Raquel (Gen 35:20), y Absalón levanta la suya en el Valle del Rey (2 Sam 18:18). El español ''estela/pilar'' y el árabe ''nusub'' (نُصُب) preservan la connotación monumental de algo erigido verticalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113629, 'spa', 'Tocón, tronco remanente', 'Tocón o tronco remanente de un árbol, usado exclusivamente en Isaías 6:13 (dos veces, con y sin sufijo posesivo). Tras la devastación de la tierra, el tocón permanece como semilla de vida futura en medio de la desolación. El español ''tronco'' se distingue claramente de las traducciones de ''pilar'', confirmando que se trata de un sentido botánico genuinamente separado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113631, 'spa', 'Fortaleza, plaza fuerte', 'Posición naturalmente fortificada en terreno montañoso o rocoso, utilizada como lugar de refugio militar o escondite. Las fortalezas del desierto donde David escapó de Saúl (1 Sam 23:14, 19) y las cuevas montañosas de Jueces 6:2 son ejemplos paradigmáticos. La construcción con «peñas» (Is 33:16) subraya el carácter pétreo y escarpado de estos refugios defensivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113638, 'spa', 'Escurrir, exprimir (Qal)', 'Qal activo: escurrir, exprimir o secar estrujando; el sujeto realiza la acción de exprimir sobre un líquido o un objeto que lo contiene. Gedeón ''exprimió el rocío del vellón'' (Jue 6:38); Jerusalén personificada ''apuró'' la copa del aturdimiento (Is 51:17); Ezequiel repite la imagen con Oholibá apurando su copa (Ez 23:34); los impíos ''apuran'' las heces del vino (Sal 75:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113639, 'spa', 'Ser exprimido (Nifal)', 'Nifal pasivo: ser escurrido o exprimido, describiendo el líquido o la sangre sacrificial que sufre el proceso de drenaje. En Lv 1:15 y 5:9, la sangre de la ofrenda de ave ''será exprimida'' (נִמְצָה) al pie del altar, como instrucción ritual precisa. Sal 73:10 extiende la imagen: las aguas del juicio ''son apuradas'' por el pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113646, 'spa', 'Pan ácimo o tortas planas preparadas sin levadura, usados en la celebración de l', 'Pan ácimo o tortas planas preparadas sin levadura, usados en la celebración de la Pascua (Ex 12:8, 15-18), las ofrendas de cereal (Lv 2:4-5), las ofrendas de paz (Lv 7:12) y la consagración sacerdotal (Ex 29:2). La ausencia de levadura es el rasgo esencial. Ya sea como alimento de emergencia cuando Lot recibe a los ángeles (Gn 19:3) o como mandato litúrgico durante la Fiesta de los Panes sin Levadura (חַג הַמַּצּוֹת), el término abarca tanto el pan en sí como la festividad de siete días.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113657, 'spa', 'Contienda o discordia', 'Contienda o riña entre personas. Proverbios 13:10 declara que «de la soberbia solo viene contienda», mientras que 17:19 advierte sobre quien ama la disputa. Isaías 58:4 reprende a Israel: «He aquí que ayunáis para contienda y riña, y para herir con el puño inicuamente». Los testimonios multilingües lo traducen consistentemente como conflicto o disputa, confirmando su sentido de confrontación activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113663, 'spa', 'Red o trampa', 'Red utilizada para cazar o atrapar, que funciona principalmente en metáforas de juicio divino o manipulación mágica. Dios como cazador extiende redes sobre el Israel rebelde; las falsas profetisas usan «redes» espirituales para capturar almas. Las glosas interlingüísticas («red», «trampa», «lazo») identifican de manera consistente el instrumento de captura, y el término genera una imagen vívida de juicio inevitable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113665, 'spa', 'Fortaleza, plaza fuerte (lugar de refugio) — una fortaleza, bastión o lugar fort', 'Fortaleza, plaza fuerte (lugar de refugio) — una fortaleza, bastión o lugar fortificado de refugio, el sentido dominante con 18 apariciones. Abarca las fortalezas de David en el desierto (1 S 22:4-5; 24:22; 2 S 5:17; 23:14), la ciudadela conquistada de Sion (2 S 5:7, 9), el nido del águila en la peña elevada (Job 39:28) y la frecuente aplicación figurada a Dios como protector en los Salmos (Sal 18:2; 31:3; 71:3; 91:2; 144:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113668, 'spa', 'Red, trampa (instrumento de caza) — una red o trampa usada para atrapar presas, ', 'Red, trampa (instrumento de caza) — una red o trampa usada para atrapar presas, un sentido homónimo completamente distinto de ''fortaleza,'' que aparece solo en Job 19:6. Job clama que Dios ''me ha rodeado con su red,'' empleando la imagen de un animal cazado atrapado en una malla. El BDB lo trata como un lexema separado (homónimo II de מְצוּדָה).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113673, 'spa', 'mandamiento divino', 'Mandamiento o precepto dado por Dios como legislación del pacto: las מִצְוֹת que Israel está llamado a guardar. Se usa tanto en singular para designar el código completo de instrucción divina como en plural para preceptos específicos. Es central en la teología deuteronómica (Dt 6:1; 8:1) y en la piedad de los Salmos (Sal 119), donde obedecerlas equivale a amar a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113680, 'spa', 'mandato, orden autoritativa', 'Mandato, directiva o decreto emitido por una autoridad humana — rey, comandante o sacerdote — típicamente en la construcción ''conforme al mandato de''. Se encuentra en narrativas históricas donde se ejerce autoridad real: el mandato del rey en 2 Cr 24:21; 30:12. Este registro ejecutivo y administrativo se distingue del sentido covenantal por su contexto de poder humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113719, 'spa', 'Profundidad, abismo', 'Las profundidades marinas o aguas abismales en sentido literal, especialmente el Mar Rojo donde Dios arrojó al ejército del faraón (Éx 15:5; Neh 9:11). Leviatán hace hervir el abismo como un caldero (Job 41:31) y los marineros contemplan las maravillas de Dios en lo profundo (Sal 107:24). Jonás se hunde en la metsulah en el corazón de los mares (Jon 2:3). La palabra siempre transmite inmensidad, poder y la fuerza arrolladora del agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113729, 'spa', 'Angustia, aflicción', 'Estado de penuria severa, presión de asedio o angustia sin escapatoria fácil. En Deuteronomio 28:53, 55, 57 y Jeremías 19:9 aparece junto a matsor (''asedio'') describiendo condiciones extremas de hambruna. En 1 Samuel 22:2 caracteriza a los hombres desesperados que se unieron a David. En el Salmo 119:143 denota angustia personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113734, 'spa', 'Angustia, aflicción', 'Un estado de angustia severa, aflicción o tribulación: la sensación de estar cercado y abrumado sin escapatoria. Las apariciones bíblicas incluyen formas plurales con sufijos pronominales (''de sus aflicciones'', ''de mis angustias'') y formas absolutas y constructas. En Job 15:24 la angustia prevalece sobre el impío; en Sofonías 1:15 integra la descripción del Día de YHWH; y en el Salmo 107 es la condición de la que Dios repetidamente libera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113738, 'spa', 'El acto, estado o condición de asediar una ciudad, incluyendo la operación milit', 'El acto, estado o condición de asediar una ciudad, incluyendo la operación militar y su duración. Aparece frecuentemente con preposiciones: ''en el asedio'' (Dt 20:19; 2 R 24:10; Jer 52:5) y en la sombría combinación ''en asedio y en angustia'' (Dt 28:53, 55, 57; Jer 19:9). El asedio simbólico de Jerusalén por Ezequiel (Ez 4:2-8; 5:2) da al término un papel profético prominente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113744, 'spa', 'Un lugar fortificado, fortaleza o estructura defensiva — a veces referido a una ', 'Un lugar fortificado, fortaleza o estructura defensiva — a veces referido a una ciudad amurallada o incluso a Egipto como tierra de fortificaciones. El Cronista lo usa para las ciudades fortificadas de Salomón y Roboam (2 Cr 8:5; 11:5), mientras que los Salmos y los profetas lo invocan para expresar confianza en la protección divina. El español alterna a ''fortaleza'', revelando el giro semántico del asedio al bastión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113754, 'spa', 'Designación poética de Egipto', 'Nombre poético para Egipto que aparece únicamente en literatura profética. El término se encuentra en el oráculo de Isaías sobre los cursos de agua fallidos de Egipto (Is 19:6), en pasajes paralelos sobre la jactancia de Senaquerib (2 Re 19:24 = Is 37:25) y en Miqueas 7:12, donde se usa en contexto escatológico, vislumbrando gente que vendrá desde Asiria y ''las ciudades de Matsor''. La raíz hebrea lo vincula al concepto de asedio o fortificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113755, 'spa', 'Fortaleza, fortificación', 'Fortificación, baluarte u obra de asedio — estructura militar defensiva o las obras ofensivas erigidas para sitiarla. En 2 Crónicas aparece repetidamente en la expresión ''ciudades fortificadas'' describiendo el programa defensivo de Roboam en todo Judá (2 Cr 11:10-11, 23; 12:4; 14:6; 21:3). En Nahúm 2:2 designa el baluarte que los defensores de Nínive deben custodiar. Isaías 29:3 lo usa para las obras de asedio contra Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113762, 'spa', 'frente', 'La frente o ceño físico, y por extensión figurada un símbolo de audacia, desafío u obstinación. En sentido literal: lugar donde la piedra de David golpeó a Goliat (1 S 17:49), donde la lepra brotó en Uzías (2 Cr 26:19–20), donde Aarón llevaba la inscripción sagrada (Éx 28:38) y donde se puso una marca protectora sobre los fieles (Ez 9:4). En sentido figurado: la ''frente de bronce'' de Israel señala una rebeldía terca (Is 48:4) y más dura que el pedernal (Ez 3:7–9), mientras Jeremías acusa a la nación infiel de tener ''frente de ramera'' que se niega a avergonzarse (Jer 3:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113776, 'spa', 'címbalos', 'Un par de címbalos metálicos usados en el culto israelita, sinónimo tardío de צֶלְצְלִים (cf. 2 S 6:5 vs. 1 Cr 13:8). Atestiguado exclusivamente en contextos cúltico-musicales: las designaciones levíticas de Asaf, Hemán y Etán (1 Cr 15:16, 19; 25:1, 6), el traslado del arca (1 Cr 13:8; 15:28), el servicio diario del templo (1 Cr 16:5, 42), las reformas de Ezequías (2 Cr 29:25), la dedicación de Salomón (2 Cr 5:12–13), la colocación de los cimientos del Segundo Templo (Esd 3:10) y la dedicación del muro de Nehemías (Neh 12:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113781, 'spa', 'Turbante sacerdotal', 'El turbante oficial de lino del sumo sacerdote israelita, enrollado sobre la cabeza y portador de la placa de oro inscrita «Santo a Jehová» (Éx 28:4, 36-37, 39; 29:6; 39:28, 31). Moisés lo colocó sobre la cabeza de Aarón en su consagración (Lv 8:9) y se vestía en el Día de la Expiación (Lv 16:4). Ezequiel emplea el término en un oráculo profético: «quita el turbante, retira la corona», como símbolo de inversión del orden establecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113785, 'spa', 'Pasos o pisadas', 'Pasos o pisadas, en sentido literal o figurado para referirse al camino de vida. El Salmo 37:23 declara que «los pasos del hombre son confirmados por el SEÑOR cuando se deleita en su camino». Proverbios 20:24 pregunta: «los pasos del hombre son del SEÑOR; ¿cómo, pues, entenderá el hombre su camino?», reconociendo la soberanía divina. Daniel 11:43 lo usa espacialmente: «a sus pasos», significando en su séquito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113787, 'spa', 'Pequenez o escasez', 'Pequenez en tamano o numero: una cosa pequena, unos pocos. Lot describe a Zoar como ''cosa pequena'' (Gn 19:20), es decir, una ciudad diminuta e insignificante. En 2 Cr 24:24, la fuerza aramea era de ''pocos hombres'' y sin embargo derroto al gran ejercito de Juda por juicio divino. Job 8:7 contrasta un comienzo ''pequeno'' con un final grandemente aumentado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113790, 'spa', 'Mizpa (topónimo)', 'Nombre propio aplicado a varias ciudades israelitas y transjordanas, todas con el sentido etimológico de ''atalaya'', de la raíz tsapah. Lugares clave incluyen Mizpa en la Sefela de Judá (Jos 15:38), Mizpa de Galaad por donde pasó Jefté en su campaña (Jue 11:29) y una Mizpa benjaminita (Jos 18:26). Las variantes «Mizpa» y «Mispá» reflejan distintas tradiciones de transliteración al español.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113796, 'spa', 'Nombre propio de lugar que significa ''atalaya'', referido a multiples sitios bibl', 'Nombre propio de lugar que significa ''atalaya'', referido a multiples sitios biblicos. Mizpa en Benjamin era un punto de asamblea nacional (Jue 20:1; 1 Sam 7:5) y centro administrativo posxilico (2 R 25:23; Jer 40:6-10). Mizpa en Galaad figura en el pacto de Laban (Gn 31:49) y en la historia de Jefte (Jue 11:11, 34). Un tercer sitio cerca del Hermon aparece en Jos 11:3. Todas las traducciones transliteran el nombre en lugar de traducirlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113811, 'spa', 'Angustia o estrecheces', 'Estrecheces o angustia extrema, a menudo peligro mortal. El Salmo 116:3 empareja «las angustias del Seol» con «los lazos de la muerte», señalando un peligro extremo. El Salmo 118:5 proclama: «desde la angustia invoqué al SEÑOR; el SEÑOR me respondió con amplitud», pasando de la constricción al alivio espacioso. Lamentaciones 1:3 describe a los enemigos de Judá alcanzándola «entre las estrecheces», en su estado vulnerable y confinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113812, 'spa', 'La tierra y nación de Egipto (מִצְרַיִם) usada como nombre propio geográfico y p', 'La tierra y nación de Egipto (מִצְרַיִם) usada como nombre propio geográfico y político. En Gn 41:55-56, ''toda la tierra de Egipto'' sufre hambre; en Gn 45:2, el llanto de José se oye en la casa de Faraón en Egipto. Este uso geográfico domina las ocurrencias, abarcando las narraciones desde la estancia de José hasta el Éxodo y más allá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113813, 'spa', 'Adjetivo o sustantivo gentilicio masculino que designa a un hombre egipcio o a u', 'Adjetivo o sustantivo gentilicio masculino que designa a un hombre egipcio o a un grupo de hombres egipcios. Potifar es ''un hombre egipcio'' (אִישׁ מִצְרִי, Gn 39:1); el egipcio a quien Moisés mató (Ex 2:11-12) se identifica con este mismo término. El plural הַמִּצְרִים designa a los egipcios como pueblo colectivo (Gn 12:12, 14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113816, 'spa', 'Adjetivo o sustantivo gentilicio femenino para una mujer egipcia o mujeres egipc', 'Adjetivo o sustantivo gentilicio femenino para una mujer egipcia o mujeres egipcias. Agar es llamada constantemente ''la egipcia'' (הַמִּצְרִית) en Gn 16:1, 3 y 21:9, y la madre de Ismael se identifica así en Gn 25:12. Las parteras egipcias se contrastan con ''las mujeres hebreas'' en Ex 1:19 usando el plural femenino מִצְרִיּוֹת.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113829, 'spa', 'Egipto (la tierra)', 'La entidad geográfica y política de Egipto: la tierra, su pueblo y su gobierno como potencia extranjera definitoria en la narrativa de Israel. Cubre todas las construcciones preposicionales: habitar en, salir de, descender a, y oráculos proféticos contra Egipto. Más de 631 apariciones (Gn 37:36; Éx 1:1; Is 19:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113836, 'spa', 'Mizraim (hijo de Cam)', 'El nombre propio Mizraim, hijo de Cam y nieto de Noé, antepasado epónimo del pueblo egipcio en la Tabla de las Naciones. Se distingue del sentido territorial por su uso masculino singular y su contexto genealógico. Limitado a cuatro pasajes (Gn 10:6, 13; 1 Cr 1:8, 11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113847, 'spa', 'Martillos', 'Martillos para construcción o trabajo en metal. En 1 Reyes 6:7 se señala que durante la edificación del templo «no se oyó martillo ni hacha ni herramienta de hierro alguna» en el sitio de la obra. Isaías 44:12 describe al herrero: «lo trabaja con martillos y lo forja». Jeremías 10:4 retrata la fabricación de ídolos: «con clavos y martillos los fijan para que no se muevan».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113850, 'spa', 'Maqueda (nombre propio, ciudad)', 'Nombre propio de lugar que designa una ciudad cananea fortificada en la Sefela, cerca de Bet-horón y Libna. Las nueve ocurrencias se concentran en la narrativa de la campaña meridional de Josué (Jos 10:10, 16, 17, 21, 28, 29; 12:16; 15:41). La evidencia multilingüe transliterada uniformemente — español ''Maqueda'', francés y alemán ''Makkedah'' — confirma su condición de topónimo único e inequívoco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113854, 'spa', 'Lugar sagrado singular', 'Lugar sagrado singular: el tabernáculo, el templo o cualquier sitio apartado para el culto divino y la morada de la presencia de Dios. Abarca la gran mayoría de las ocurrencias, desde el ''santuario que tus manos establecieron'' del Cántico del Mar (Ex 15:17) hasta las regulaciones levíticas detalladas sobre el acercamiento al lugar santo (Lv 12:4; 16:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113867, 'spa', 'Forma plural que designa múltiples lugares sagrados o los diversos recintos dent', 'Forma plural que designa múltiples lugares sagrados o los diversos recintos dentro de un complejo del templo. A veces se refiere a divisiones legítimas del santuario (Sal 68:35; 73:17, ''entré en los santuarios de Dios''), pero también puede denotar los lugares altos condenados y santuarios ilegítimos que Dios promete devastar (Lv 26:31) o los santuarios profanados de Jerusalén (Jer 51:51; Ez 21:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113876, 'spa', 'Ocurrencia singular en Nm 18', 'Ocurrencia singular en Nm 18:29 donde la palabra denota una porción consagrada en lugar de un lugar físico: la mejor parte (literalmente ''su porción santa'') separada del diezmo levítico como ofrenda al Señor. Una extensión donde la santidad pasa del espacio sagrado a la asignación sagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113891, 'spa', 'Región de Cilicia', 'Designación territorial de la región de Cilicia, que aparece en textos sobre el comercio de caballos de Salomón (1 Re 10:28 dos veces, 2 Cr 1:16 dos veces). El contexto indica que Qué era una fuente principal de importación de caballos hacia Israel, junto con Egipto. La antigua Cilicia era célebre por sus caballos en los registros neoasirios. Las variantes textuales (מִקְוֵה/מִקְוֵא) y la evidencia de las versiones respaldan esta identificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113892, 'spa', 'Esperanza en Dios', 'Esperanza o expectativa fundamentada especialmente en Dios. Expresa la esperanza humana que halla su base en la fidelidad divina. David reconoce que aparte de Dios la existencia terrenal no ofrece ''esperanza'' (1 Cr 29:15), mientras que Secanias insiste en que a pesar de la ruptura del pacto, ''hay esperanza para Israel'' mediante el arrepentimiento (Esd 10:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113893, 'spa', 'Reunión de aguas', 'Reunión o acumulación, principalmente de agua. Génesis 1:10 registra que «Dios llamó a la reunión de las aguas Mares», el acumulamiento primordial que dejó al descubierto la tierra seca. Éxodo 7:19 se refiere a «todos los depósitos de agua» en Egipto que se convertirían en sangre. Levítico 11:36 distingue «un manantial o depósito de agua» como algo que permanece limpio aun al contacto con un animal impuro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113895, 'spa', 'lugar, sitio, localidad', 'Lugar físico, sitio, localidad o posición designada (más de 400 apariciones). Este sentido abrumadoramente dominante cubre desde la tierra sagrada de la zarza ardiente (Éx 3:5) hasta el lugar donde Abraham se presentó ante el Señor (Gn 18:24), pasando por regiones y localidades con nombre. Todas las traducciones principales convergen en un solo término espacial nuclear.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113938, 'spa', 'distancia, espacio', 'Distancia medida o espacio intermedio (una sola aparición en 1 S 26:13). David cruzó y se situó en la cima de un monte ''a distancia'', interponiendo espacio entre él y el campamento de Saúl. Esta acepción rara capta a מָקוֹם como la extensión o intervalo entre dos puntos, no como ubicación fija.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113949, 'spa', 'Manantial, fuente, origen — una fuente o manantial de agua, empleado predominant', 'Manantial, fuente, origen — una fuente o manantial de agua, empleado predominantemente en contextos figurados. Dios mismo es llamado la ''fuente de aguas vivas'' (Jer 2:13; 17:13), y el Salmo 36:9 declara ''contigo está la fuente de la vida.'' Proverbios extiende la metáfora a la sabiduría, la enseñanza y el temor del SEÑOR como fuentes vivificantes (Pr 10:11; 13:14; 14:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113952, 'spa', 'Flujo, emisión corporal — un flujo o descarga corporal, específicamente el flujo', 'Flujo, emisión corporal — un flujo o descarga corporal, específicamente el flujo de sangre en el contexto de las regulaciones levíticas de pureza (Lv 20:18). Aquí la imagen hidráulica concreta de un manantial se transfiere al cuerpo humano. Este uso marca un dominio semántico distinto del figurado ''fuente de vida.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113963, 'spa', 'Varas o palos — varas o palos usados con un propósito práctico específico, sobre', 'Varas o palos — varas o palos usados con un propósito práctico específico, sobre todo las varas de madera peladas que Jacob colocó ante los abrevaderos para influir en las marcas de sus rebaños (Gn 30:37-41). La forma plural מַקְלוֹת domina este sentido, destacando su función como instrumentos elaborados más que ramas naturales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113964, 'spa', 'Cayado o bastón — un cayado o bastón que lleva una persona como implemento perso', 'Cayado o bastón — un cayado o bastón que lleva una persona como implemento personal: la vara del pastor, el bastón del peregrino o un símbolo de autoridad y cargo. Jacob recuerda haber cruzado el Jordán solo con su cayado (Gn 32:10), los israelitas comen la Pascua con el bastón en la mano (Éx 12:11), y Jeremías lamenta la quiebra del ''bastón de fuerza'' de Moab (Jer 48:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113967, 'spa', 'Rama de árbol — una rama o brote aún unido o recién cortado de un árbol, enfatiz', 'Rama de árbol — una rama o brote aún unido o recién cortado de un árbol, enfatizando su origen botánico. En la visión inaugural de Jeremías (Jer 1:11), Dios muestra al profeta un מַקֵּל שָׁקֵד — una rama de almendro — como juego de palabras sobre la vigilancia divina (שֹׁקֵד). Aquí el sentido botánico es primario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113972, 'spa', 'Garrote o arma — un garrote o palo pesado blandido como arma de guerra', 'Garrote o arma — un garrote o palo pesado blandido como arma de guerra. En Ezequiel 39:9, entre el equipo militar quemado tras la derrota de Gog, el מַקֵּל aparece junto a escudos, arcos y lanzas. Este uso marcadamente bélico lo distingue del pacífico cayado del pastor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113977, 'spa', 'Nombre personal benjaminita', 'Nombre personal benjaminita llevado por al menos dos individuos: (1) Un descendiente en la genealogía del rey Saúl, mencionado en 1 Crónicas 8:32 y 9:37-38 como parte de las familias que residían en Jerusalén. (2) Un oficial que sirvió bajo David según 1 Crónicas 27:4, aunque esta referencia no aparece en la Septuaginta, lo cual genera incertidumbre sobre su historicidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113978, 'spa', 'Refugio, ciudad de refugio — asilo o refugio legal que designa las seis ciudades', 'Refugio, ciudad de refugio — asilo o refugio legal que designa las seis ciudades levíticas apartadas bajo la ley de la Torá para amparar a quienes cometieron homicidio accidental, protegiéndolos de la venganza de sangre (Nm 35:6-32; Jos 20:2-3; 21:13-38; 1 Cr 6:42, 52). El término nunca se usa metafóricamente ni en referencia a Dios; funciona exclusivamente como un sustantivo jurídico-institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113983, 'spa', 'Tallado decorativo del templo', 'Obra tallada o grabada que se hallaba en las superficies del templo. En 1 Reyes 6:18 describe los ornamentos tallados en el cedro del interior. Los versículos 6:29 y 32 se refieren a tallas de querubines, palmeras y flores en muros y puertas. La última aparición (7:31) describe grabados en las bases de bronce que sostenían las fuentes. Las traducciones multilingües emplean consistentemente términos de escultura y relieve.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (113984, 'spa', 'Sustantivo colectivo para ganado doméstico', 'Sustantivo colectivo para ganado doméstico: vacas, ovejas, cabras, burros y camellos vistos como propiedad pastoral mueble. La riqueza de Abraham se mide en מִקְנֶה (Gn 13:2); las plagas golpean el ganado de Egipto (Ex 9:3); y las tribus de Transjordania tienen abundante ganado que requiere pastizales (Nm 32:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114008, 'spa', 'Sentido abstracto o comercial ligado a la raíz q-n-h (''adquirir'')', 'Sentido abstracto o comercial ligado a la raíz q-n-h (''adquirir''): el acto de comprar, el precio de adquisición o las posesiones en sentido amplio. En Gn 49:32, el מִקְנֶה de Jacob se enumera junto a su cueva de sepultura como ''adquisición''; en Gn 26:14, el מִקְנֶה de Isaac denota sus posesiones en conjunto. El sentido se desplaza de los animales al concepto de adquisición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114027, 'spa', 'compra, adquisición, precio', 'Sustantivo femenino que denota el acto de comprar, el precio de compra o lo adquirido mediante transacción. Prominente en la fuente sacerdotal: ''comprado por dinero'' (מִקְנַת כֶּסֶף, Gn 17:12–13, 23, 27; Éx 12:44) describe a miembros del hogar incluidos en el pacto de la circuncisión. En Jeremías 32:11–16, el ''documento de compra'' (סֵפֶר הַמִּקְנָה) sirve como símbolo profético de esperanza durante el asedio babilónico. Levítico 25 lo emplea para calcular el precio de la tierra en relación con los años de jubileo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114038, 'spa', 'Esquina, ángulo', 'Esquina, ángulo o contrafuerte angular donde dos superficies de muro se encuentran. Se usa para los bastidores de esquina del tabernáculo unidos de abajo a arriba (Éx 26:24; 36:29), la fortificación del «Ángulo» en el muro de Jerusalén (Neh 3:19-25), la torre de Uzías en el contrafuerte angular (2 Cr 26:9), y las esquinas del altar y los atrios angulares cerrados del templo visionario de Ezequiel (Ez 41:22; 46:21-22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114046, 'spa', 'Pudrirse, consumirse (Nifal)', 'Pudrirse, descomponerse, consumirse o languidecer en la conjugación Nifal, describiendo la descomposición física o el desgaste de carne, heridas o personas enteras bajo el juicio divino. Abarca llagas supurantes (Sal 38:5), disolución cósmica del ejército celestial (Is 34:4), desgaste corporal en el exilio (Ez 4:17; 24:23; 33:10) y lenguaje de maldición pactual donde los desobedientes se consumen en tierra enemiga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114051, 'spa', 'Pudrir, causar podredumbre (Hifil)', 'El infinitivo absoluto Hifil usado adverbialmente para intensificar la descripción de la putrefacción, funcionando como forma causativa o enfática. Atestiguado en Zacarías 14:12 en un vívido oráculo de plaga: la carne de quienes guerreen contra Jerusalén se pudrirá estando aún en pie, sus ojos se pudrirán en sus cuencas y sus lenguas se pudrirán en sus bocas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114054, 'spa', 'Una convocación o asamblea sagrada, especialmente en la expresión técnica sacerd', 'Una convocación o asamblea sagrada, especialmente en la expresión técnica sacerdotal מִקְרָא־קֹדֶשׁ (''santa convocación'') que designa las reuniones solemnes festivas de Israel en sábado y fiestas señaladas (Éx 12:16; Lv 23:2-37; Nm 28-29). El español ''convocación'' conserva el sentido raíz de ''llamar juntos.'' Isaías 1:13 y 4:5 usan el término fuera del corpus sacerdotal, mostrando su extensión más allá del calendario litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114059, 'spa', 'El acto de lectura o recitación de las Escrituras, de la misma raíz קָרָא en su ', 'El acto de lectura o recitación de las Escrituras, de la misma raíz קָרָא en su sentido de ''leer en voz alta.'' Atestiguado únicamente en Nehemías 8:8, donde Esdras y los levitas leyeron del libro de la Ley y dieron el sentido (בַּמִּקְרָא). Este sentido postexílico anticipa la tradición sinagogal de lectura pública de la Torá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114062, 'spa', 'Suceso, destino, suerte', 'Un suceso, destino, fortuna o suerte: los acontecimientos que le sobrevienen a alguien como su porción o destino. Usado extensamente en Eclesiastés, donde Qohélet observa que un mismo miqreh alcanza a todos sin importar sabiduría o necedad (Ecl 2:14-15), y la misma suerte recae sobre humanos y animales por igual (Ecl 3:19). El tono es grave y filosófico, cuestionando si existe alguna distinción con sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114063, 'spa', 'Casualidad, accidente', 'Casualidad, accidente o coincidencia: un evento que ocurre al azar sin causación divina o intencional evidente. En Rut 2:3, el narrador usa miqreh para describir la llegada aparentemente fortuita de Rut al campo de Booz, aunque el lector percibe la providencia bajo la superficie. En 1 Samuel 6:9, los filisteos se preguntan si la plaga provenía del Dios de Israel o era mera casualidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114071, 'spa', 'Obra batida a martillo', 'Trabajo en metal labrado o batido a martillo, específicamente oro o plata labrados por martilleo experto para los utensilios del tabernáculo. Los querubines de oro sobre el propiciatorio eran miqshah —labrados a martillo de una sola pieza en vez de fundidos en molde (Éx 25:18; 37:7). La menorá era enteramente miqshah, batida de un talento de oro, desde su base hasta sus copas en forma de flor (Éx 25:31, 36; 37:17, 22; Nm 8:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114073, 'spa', 'Obra torneada o campo', 'Uso distinto o posiblemente homónimo en Jeremías 10:5, donde el contexto difiere por completo de los pasajes sobre metalurgia del tabernáculo. La tradición de la LXX y Baruc traduce ''en un campo de pepinos'', comparando los ídolos mudos con un espantapájaros. La alternativa ''obra torneada'' sugiere una artesanía pulida o moldeada aplicada a la fabricación de ídolos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114075, 'spa', 'El sentido fisico fundamental', 'El sentido fisico fundamental: algo que sabe aspero, acre o desagradable. Aplicado a las aguas de Mara (Ex 15:23), al alimento que una persona hambrienta comera de todas formas (Pr 27:7) y al ''agua amarga'' de la prueba en Numeros 5:18-24. Las traducciones en todos los idiomas emplean uniformemente vocabulario gustativo (''amargo''), confirmando este como el nucleo semantico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114078, 'spa', 'En cadenas constructas que describen a personas cuya disposicion interior es ama', 'En cadenas constructas que describen a personas cuya disposicion interior es amarga, feroz o desesperada. Los hombres de David en Adulam eran ''amargos de alma'' (1 Sam 22:2), los hombres de Dan eran ''fieros de animo'' (Jue 18:25) y Job lamenta que se da luz ''al amargo de alma'' (Job 3:20). El patron constructo מַר + נֶפֶשׁ/לֵב crea una descripcion compuesta de caracter.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114081, 'spa', 'Un intensificador adverbial que modifica acciones como llorar o clamar', 'Un intensificador adverbial que modifica acciones como llorar o clamar. Los mensajeros de paz ''lloran amargamente'' (Is 33:7) y los marineros ''claman amargamente'' por Tiro (Ez 27:30). La funcion gramatical adverbial se distingue de los sentidos adjetivales, expresando la intensidad de la accion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114083, 'spa', 'Usado como sustantivo que denota la condicion abstracta de amargura, angustia o ', 'Usado como sustantivo que denota la condicion abstracta de amargura, angustia o afliccion. Agag camina ''en la amargura de la muerte'' (1 Sam 15:32) y Job habla ''en la amargura de mi alma'' (Job 7:11; 10:1). El hebreo pasa gramaticalmente del adjetivo al sustantivo para expresar el estado interior de profunda afliccion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114095, 'spa', 'Mirra (resina aromática)', 'Gomorresina aromática de los árboles de Commiphora, valorada como perfume de lujo e ingrediente sagrado. Es el componente principal del aceite santo de unción (Éx 30:23), se usa en el tratamiento de belleza de Ester (Est 2:12), se entreteje a lo largo del Cantar de los Cantares como imagen del deseo (Cnt 1:13; 4:6; 5:1, 5) y se aplica a las vestiduras del rey mesiánico (Sal 45:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114103, 'spa', 'Señor, amo', 'Título arameo que significa ''señor'' o ''amo'', usado en Daniel tanto para Dios (''Señor de reyes'', Dan 2:47; ''Señor del cielo'', Dan 5:23) como tratamiento deferente al rey (''mi señor'', Dan 4:19, 24). El Ketiv lee mor''i mientras el Qere tiene mari, preservando una variación dialectal en el sufijo de primera persona. El español ''mi señor'' captura fielmente ambos usos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (114108, 'spa', 'apariencia, aspecto exterior', 'La forma visual externa o aspecto de una persona, criatura u objeto, abarcando belleza, semblante y presentación general. Es el sentido dominante (83 apariciones), usado de mujeres hermosas como Sara y Rebeca, del siervo del Señor cuya apariencia fue desfigurada (Is 52:14) y del rostro saludable de Daniel (Dn 1:15).');